#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.."&&pwd)";. "$ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.sh";S="$(jc_fl_test_root_create JC_FL_TEST_DOCKER_QUERY_V1)";ACTIVE='';AUX_ROOT=''
cleanup(){ local original=$? ok=1;set +e;if [ -n "$ACTIVE" ]&&[ -d "$ACTIVE" ];then jc_fl_test_run_cleanup "$ACTIVE"||ok=0;fi;if [ "$ok" = 1 ];then jc_fl_test_root_finalize "$S"||ok=0;fi;if [ -n "$AUX_ROOT" ]&&[ -d "$AUX_ROOT" ];then rm -rf "$AUX_ROOT"||ok=0;fi;if [ "$ok" != 1 ];then echo "docker_query_test: cleanup retained evidence at root=$S active=${ACTIVE:-none}" >&2;fi;[ "$original" -ne 0 ]&&return "$original";[ "$ok" = 1 ];};trap cleanup EXIT
fail(){ echo "fair_launch_local_e2e_docker_query_test: FAIL: $*" >&2;exit 1;}
clean_active(){ local d="$ACTIVE";jc_fl_test_run_cleanup "$d";ACTIVE='';}
# Successful-empty name discovery cannot hide the authoritative returned ID: exact-ID cleanup wins and no state remains.
set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_FAIL_AT=docker_created_no_id JC_FL_E2E_TEST_DOCKER_QUERY_FAIL='ps -aq empty' bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/prefer-id.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];[ -z "$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)" ]||fail 'authoritative ID was not preferred'
# Exact-ID inspect failure retains full recovery evidence and the untouched fixture.
set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_FAIL_AT=docker_created_no_id JC_FL_E2E_TEST_DOCKER_QUERY_FAIL='inspect --format timeout' bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/exact-fail.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];d="$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";e="$d/evidence/start-failure.json";[ "$(stat -Lc '%a' "$d" "$e" "$d/evidence/docker-created.source.json")" = $'700\n600\n600' ];grep -Fq mysql-exact-id-query-failed "$e";clean_active
# Malformed successful Docker stdout is never authority. The actual test-owned ID is separately retained only by the allowlisted hook for exact test cleanup.
for kind in short multiple malformed;do set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_DOCKER_RUN_OUTPUT="$kind" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/malformed-$kind.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];d="$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";grep -Fq docker-run-output-malformed "$d/evidence/start-failure.json";python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$d/evidence/docker-created.source.json">/dev/null;clean_active;done
# Lifecycle failed-start removal failure preserves authoritative ID and mode-600 evidence.
set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_FAIL_AT=after_mysql JC_FL_E2E_TEST_LIFECYCLE_DOCKER_RM_FAIL=1 bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/lifecycle-rm-fail.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];d="$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";[ "$(stat -Lc %a "$d/evidence/start-container-removal.json.rm-output" "$d/evidence/start-container-removal.json.source.json" "$d/evidence/start-container-removal.json.source.json.removal.json")" = $'600\n600\n600' ];clean_active
# Lifecycle failed-start post-rm query failure retains exact authority/evidence until explicit recovery absence proof.
set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_FAIL_AT=after_mysql JC_FL_E2E_TEST_LIFECYCLE_POST_RM_QUERY_FAIL=1 bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/lifecycle-query-fail.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];d="$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";[ "$(stat -Lc %a "$d/evidence/start-container-removal.json.source.json" "$d/evidence/start-container-removal.json.source.json.removal.json" "$d/evidence/start-container-removal.json.source.json.post-rm-query.raw")" = $'600\n600\n600' ];clean_active
# Helper Docker rm failure preserves the live fixture and record/evidence.
out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$S/$run";ACTIVE="$d";jc_fl_test_canonical_container_record "$d" "$d/evidence/test-container-cleanup.json";set +e;JC_FL_E2E_TEST_CONTAINER_RM_FAIL=1 jc_fl_test_container_remove "$d/evidence/test-container-cleanup.json";rc=$?;set -e;[ "$rc" -ne 0 ];[ -f "$d/evidence/test-container-cleanup.json" ]&&[ -f "$d/evidence/test-container-cleanup.json.rm-failure" ];id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$d/evidence/test-container-cleanup.json")";docker inspect "$id">/dev/null;rm -f "$d/evidence/test-container-cleanup.json.rm-failure";jc_fl_test_container_remove "$d/evidence/test-container-cleanup.json";jc_fl_test_redis_remove "$d";jc_fl_test_run_delete "$d";ACTIVE=''
# Post-rm query failure preserves record and evidence until a fresh exact-ID absence proof finalizes cleanup.
out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$S/$run";ACTIVE="$d";jc_fl_test_canonical_container_record "$d" "$d/evidence/test-container-cleanup.json";set +e;JC_FL_E2E_TEST_CONTAINER_POST_RM_QUERY_FAIL=1 jc_fl_test_container_remove "$d/evidence/test-container-cleanup.json";rc=$?;set -e;[ "$rc" -ne 0 ];[ -f "$d/evidence/test-container-cleanup.json" ]&&[ -f "$d/evidence/test-container-cleanup.json.post-rm-query.raw" ];jc_fl_test_container_finalize_absent "$d/evidence/test-container-cleanup.json";jc_fl_test_redis_remove "$d";jc_fl_test_run_delete "$d";ACTIVE=''
# Teardown residue query failures retain state after exact resources are already removed.
for inject in 'ps -aq' 'network ls';do out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$S/$run";set +e;JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_DOCKER_QUERY_FAIL="$inject" bash "$ROOT/scripts/fair-launch/local-e2e/teardown.sh" "$run">"$S/teardown.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];grep -Fq TEARDOWN_BLOCKED_DOCKER_RESIDUE_QUERY "$d/evidence/teardown-failure.json";jc_fl_test_run_delete "$d";done
# Hostile timeout parent and fake same-basename cannot bypass exact wrapper.
for phase in start apply-schema status teardown;do script="$ROOT/scripts/fair-launch/local-e2e/$phase.sh";case "$phase" in start)args=(1s);;*)args=(00000000-0000-4000-8000-000000000000 1s);;esac;before="$(date +%s%N)";set +e;JC_FL_E2E_PHASE_ACTIVE="$phase" JC_FL_E2E_TEST_PHASE_TIMEOUT=1s JC_FL_E2E_TEST_HOLD_AT="phase_entry_$phase" timeout --foreground --kill-after=5s 4s bash "$script" "${args[@]}">"$S/hostile-$phase.out" 2>&1;rc=$?;set -e;elapsed=$((($(date +%s%N)-before)/1000000));[ "$rc" = 124 ]&&[ "$elapsed" -lt 3000 ];! grep -Eq 'ready:|teardown complete|^RUN_ID=' "$S/hostile-$phase.out";done
AUX_ROOT="$(mktemp -d)";chmod 700 "$AUX_ROOT";printf '#!/usr/bin/env bash\nexec /usr/bin/timeout "$@"\n'>"$AUX_ROOT/timeout";chmod 700 "$AUX_ROOT/timeout";before="$(date +%s%N)";set +e;PATH="$AUX_ROOT:$PATH" JC_FL_E2E_PHASE_ACTIVE=start JC_FL_E2E_TEST_PHASE_TIMEOUT=1s JC_FL_E2E_TEST_HOLD_AT=phase_entry_start "$AUX_ROOT/timeout" --foreground --kill-after=5s 4s bash "$ROOT/scripts/fair-launch/local-e2e/start.sh" 1s >"$S/fake.out" 2>&1;rc=$?;set -e;elapsed=$((($(date +%s%N)-before)/1000000));[ "$rc" = 124 ]&&[ "$elapsed" -lt 3000 ];rm -rf "$AUX_ROOT";AUX_ROOT=''
# Status timeout/error vs successful absence. Canonical container removal uses complete verifier + immutable record.
out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$S/$run";ACTIVE="$d";for inject in 'inspect --format timeout' 'inspect --format error';do set +e;sout="$(JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_DOCKER_QUERY_FAIL="$inject" bash "$ROOT/scripts/fair-launch/local-e2e/status.sh" "$run" 2>&1)";rc=$?;set -e;[ "$rc" -ne 0 ];printf '%s\n' "$sout"|grep -Fq mysql_state=query_failed;done
jc_fl_test_canonical_container_record "$d" "$d/evidence/test-container-cleanup.json";jc_fl_test_container_remove "$d/evidence/test-container-cleanup.json";set +e;sout="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/status.sh" "$run" 2>&1)";rc=$?;set -e;[ "$rc" -ne 0 ];printf '%s\n' "$sout"|grep -Fq mysql_state=missing;jc_fl_test_redis_remove "$d";jc_fl_test_run_delete "$d";ACTIVE='';jc_fl_test_root_finalize "$S";trap - EXIT
 echo 'fair_launch_local_e2e_docker_query_test: PASS authoritative full ID, malformed output retention, safe cleanup, status, query, and timeout controls'
